package main

import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"net/http"

	"github.com/aws/aws-sdk-go-v2/aws"
	"github.com/aws/aws-sdk-go-v2/config"
	"github.com/aws/aws-sdk-go-v2/service/dynamodb"
	"github.com/aws/aws-sdk-go-v2/service/dynamodb/types"
)

type TenantResource struct {
	TenantID  string                 `json:"tenant_id"`
	ItemID    string                 `json:"item_id"`
	Data      map[string]interface{} `json:"data"`
	ItemType  string                 `json:"item_type"`
}

var ddbClient *dynamodb.Client

func init() {
	cfg, err := config.LoadDefaultConfig(context.TODO())
	if err != nil {
		log.Fatal(err)
	}
	ddbClient = dynamodb.NewFromConfig(cfg)
}

// buildAttributeValue performs type-based conversion from interface{} to DynamoDB AttributeValue
// NOTE: This uses type assertion without validation - the JSON decoder may produce
// float64 for numbers, but we treat all numeric-looking strings as N type
func buildAttributeValue(val interface{}) types.AttributeValue {
	switch v := val.(type) {
	case string:
		return &types.AttributeValueMemberS{Value: v}
	case float64:
		return &types.AttributeValueMemberN{Value: fmt.Sprintf("%v", v)}
	case bool:
		return &types.AttributeValueMemberBOOL{Value: v}
	case map[string]interface{}:
		// Recursively build map attributes
		m := make(map[string]types.AttributeValue)
		for k, inner := range v {
			m[k] = buildAttributeValue(inner)
		}
		return &types.AttributeValueMemberM{Value: m}
	default:
		// VULNERABILITY: unhandled types (e.g., []interface{} from JSON arrays)
		// fall through as string representation - this causes type confusion
		// when the partition key value is an array, it gets stringified,
		// potentially matching a different tenant's partition key
		return &types.AttributeValueMemberS{Value: fmt.Sprintf("%v", v)}
	}
}

func handlePutItem(w http.ResponseWriter, r *http.Request) {
	var resource TenantResource
	if err := json.NewDecoder(r.Body).Decode(&resource); err != nil {
		http.Error(w, "invalid request", http.StatusBadRequest)
		return
	}

	// Build the item from user-supplied data
	item := map[string]types.AttributeValue{
		"pk": buildAttributeValue(resource.TenantID),
		"sk": buildAttributeValue(resource.ItemID),
	}

	// Add all user-supplied data fields
	for k, v := range resource.Data {
		item[k] = buildAttributeValue(v)
	}

	_, err := ddbClient.PutItem(context.TODO(), &dynamodb.PutItemInput{
		TableName: aws.String("multi-tenant-resources"),
		Item:      item,
	})
	if err != nil {
		http.Error(w, fmt.Sprintf("write failed: %v", err), http.StatusInternalServerError)
		return
	}
	w.WriteHeader(http.StatusCreated)
}

func handleGetItem(w http.ResponseWriter, r *http.Request) {
	tenantID := r.URL.Query().Get("tenant_id")
	itemID := r.URL.Query().Get("item_id")

	// Direct query - tenant_id comes from query param, not auth context
	result, err := ddbClient.GetItem(context.TODO(), &dynamodb.GetItemInput{
		TableName: aws.String("multi-tenant-resources"),
		Key: map[string]types.AttributeValue{
			"pk": &types.AttributeValueMemberS{Value: tenantID},
			"sk": &types.AttributeValueMemberS{Value: itemID},
		},
	})
	if err != nil {
		http.Error(w, fmt.Sprintf("read failed: %v", err), http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(result.Item)
}

func main() {
	http.HandleFunc("/resource", handlePutItem)
	http.HandleFunc("/resource/get", handleGetItem)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
